    #[test]
    fn a_variant_whose_name_extends_the_pinned_one_does_not_hijack_the_pin() {
        // Internal review of PR #58: `split_once("EffectScheduled")` matched
        // `EffectScheduledV1` declared before it, so the pin read the decoy's field list
        // and the real variant grew a fifth field unseen. The same held for
        // `enum RecordRefV2`. This module already settled the convention — the
        // parser-backed trait-impl check reads a token boundary — and the pin was not
        // following it.
        let decoyed = format!(
            "pub enum RecordRef<'a> {{\n    EffectScheduledV1 {{{}}},\n    \
             EffectScheduled {{{} deadline_ms: u32,}},\n}}\n",
            pinned_body(),
            pinned_body()
        );
        let violations = check_effect_scheduled_fields(&[layer(EFFECT_SCHEDULED_PATH, &decoyed)]);
        assert!(
            violations.iter().any(|v| v.detail.contains("deadline_ms")),
            "a prefix-named decoy hijacked the pin: {violations:?}"
        );

        let decoyed_enum = format!(
            "pub enum RecordRefV2<'a> {{\n    EffectScheduled {{{}}},\n}}\n\
             pub enum RecordRef<'a> {{\n    EffectScheduled {{{} deadline_ms: u32,}},\n}}\n",
            pinned_body(),
            pinned_body()
        );
        let violations =
            check_effect_scheduled_fields(&[layer(EFFECT_SCHEDULED_PATH, &decoyed_enum)]);
        assert!(
            violations.iter().any(|v| v.detail.contains("deadline_ms")),
            "a prefix-named enum hijacked the pin: {violations:?}"
        );
    }

    #[test]
    fn a_field_named_only_in_a_string_literal_does_not_count() {
        // The other half of the comment test: `code_only` erases string literals, so a
        // message that quotes a field name cannot add one.
        let body = format!("{} /* prose */ ", pinned_body());
        let source = format!(
            "pub enum RecordRef<'a> {{\n    EffectScheduled {{{body}}},\n}}\n\
             pub const HELP: &str = \"deadline_ms: u32, priority: u8,\";\n"
        );
        assert!(
            check_effect_scheduled_fields(&[layer(EFFECT_SCHEDULED_PATH, &source)]).is_empty(),
            "a field name inside a string literal is not a field"
        );
    }

    #[test]
    fn a_generic_field_type_does_not_add_a_field() {
        // `Option<Thing>` and a function-pointer type both put angle brackets and arrows in
        // a field list; neither declares a field.
        let body = EFFECT_SCHEDULED_FIELDS
            .iter()
            .map(|field| format!(" {field}: Option<Thing>,"))
            .collect::<Vec<String>>()
            .concat();
        assert!(
            check_effect_scheduled_fields(&record_source(&body)).is_empty(),
            "a generic type is not a field"
        );
    }

    #[test]
    fn a_parameter_named_only_in_a_comment_does_not_count() {
        let Some(parameter) = INTEGRITY_CHECK_PARAMETERS.first() else {
            return;
        };
        let source = tests_support::clean_checksum_module().replace(
            &format!(" {}", parameter.literal),
            &format!(" /* {} */ 0xDEAD_BEEF", parameter.literal),
        );
        assert!(
            !check_integrity_check(&[layer(INTEGRITY_CHECK_PATH, &source)]).is_empty(),
            "a polynomial in a comment is not a polynomial"
        );
    }

    #[test]
    fn a_parameter_outside_its_own_function_does_not_count() {
        // Codex, PR #58: the pin was a presence check over the whole file, so CRC-32's
        // initial value vouched for its own final xor, and any unrelated constant could
        // keep a literal alive after its real use changed.
        let source = format!(
            "{}\npub(crate) const LEFTOVER: u32 = 0xEDB8_8320;\n",
            tests_support::clean_checksum_module().replace(" 0xEDB8_8320", " 0xDEAD_BEEF")
        );
        let violations = check_integrity_check(&[layer(INTEGRITY_CHECK_PATH, &source)]);
        assert!(
            violations
                .iter()
                .any(|v| v.detail.contains("reflected polynomial")),
            "a literal parked outside the function satisfied the pin: {violations:?}"
        );
    }

    #[test]
    fn a_missing_checksum_function_is_reported() {
        // The fail-closed direction: no `fn crc32` means the parameters are pinned against
        // nothing, and that has to be loud rather than green.
        let violations = check_integrity_check(&[layer(
            INTEGRITY_CHECK_PATH,
            "//! Nothing here.\npub(crate) const fn crc16(b: &[u8]) -> u16 { 0x1021; 0xFFFF }\n",
        )]);
        assert!(
            violations.iter().any(|v| v.detail.contains("fn crc32")),
            "{violations:?}"
        );
    }

    #[test]
    fn a_test_fixture_in_an_out_of_line_test_module_is_not_a_lookup_table() {
        // Codex, PR #58 round 3. Moving the inline tests to `crc/tests.rs` behind
        // `#[cfg(test)] mod tests;` is an ordinary refactor, and the submodule scan added
        // in the round before would have reported the bit-flip sweep's
        // `const MESSAGE: [u8; 12]` as a production table. A rule that rejects a test-only
        // refactor is a rule contributors learn to work around.
        for path in [
            "crates/waymaker-flash/src/crc/tests.rs",
            "crates/waymaker-flash/src/crc/tests/mod.rs",
        ] {
            let sources = vec![
                layer(
                    INTEGRITY_CHECK_PATH,
                    &format!(
                        "{}#[cfg(test)]\nmod tests;\n",
                        tests_support::clean_checksum_module()
                    ),
                ),
                crate::size::LayerSource {
                    crate_name: "waymaker-flash".to_owned(),
                    path: path.to_owned(),
                    contents: "const MESSAGE: [u8; 12] = [0; 12];\n".to_owned(),
                },
            ];
            assert!(
                check_integrity_check(&sources).is_empty(),
                "`{path}` was read as production code"
            );
        }
    }

    #[test]
    fn an_ungated_submodule_is_still_scanned_when_a_sibling_is_test_only() {
        // The exemption has to be per module, not "there is a cfg(test) mod somewhere".
        let sources = vec![
            layer(
                INTEGRITY_CHECK_PATH,
                &format!(
                    "{}#[cfg(test)]\nmod tests;\nmod table;\n",
                    tests_support::clean_checksum_module()
                ),
            ),
            crate::size::LayerSource {
                crate_name: "waymaker-flash".to_owned(),
                path: "crates/waymaker-flash/src/crc/tests.rs".to_owned(),
                contents: "const MESSAGE: [u8; 12] = [0; 12];\n".to_owned(),
            },
            crate::size::LayerSource {
                crate_name: "waymaker-flash".to_owned(),
                path: "crates/waymaker-flash/src/crc/table.rs".to_owned(),
                contents: "pub(crate) const NIBBLE: [u32; 16] = [0; 16];\n".to_owned(),
            },
        ];
        let violations = check_integrity_check(&sources);
        assert!(
            violations.iter().any(|v| v.detail.contains("NIBBLE")),
            "{violations:?}"
        );
        assert!(
            !violations.iter().any(|v| v.detail.contains("MESSAGE")),
            "{violations:?}"
        );
    }

    #[test]
    fn a_path_attribute_on_a_test_module_exempts_the_file_it_names() {
        // Issue #59: the old scan guessed the child file from the module name, so
        // `#[cfg(test)] #[path = "crc/tbl.rs"] mod table;` never matched `crc/tbl.rs`
        // and the test-only file's arrays were scanned as shipped lookup tables.
        // (`#[path]` resolves against the declaring file's directory — verified by
        // compiling a nested probe — so the `crc/` component is what lands the file
        // under `crc/`.)
        let sources = vec![
            layer(
                INTEGRITY_CHECK_PATH,
                &format!(
                    "{}\n#[cfg(test)]\n#[path = \"crc/tbl.rs\"]\nmod table;\n",
                    tests_support::clean_checksum_module()
                ),
            ),
            crate::size::LayerSource {
                crate_name: "waymaker-flash".to_owned(),
                path: "crates/waymaker-flash/src/crc/tbl.rs".to_owned(),
                contents: "//! Test tables.\nstatic TABLE: [u32; 256] = [0; 256];\n".to_owned(),
            },
        ];
        let violations = check_integrity_check(&sources);
        assert!(
            !violations.iter().any(|v| v.detail.contains("TABLE")),
            "a test-only table behind #[path] was scanned as a shipped lookup table: \
             {violations:?}"
        );
    }

    #[test]
    fn a_test_only_grandchild_module_is_exempt_by_inheritance() {
        // Issue #59: a `mod data;` inside `crc/tests.rs` carries no `#[cfg(test)]` of
        // its own — it is test-only because its parent is. A walk that forgets the
        // gating when it enters the child file scans the grandchild's arrays as
        // shipped lookup tables, punishing the ordinary refactor of moving test
        // helpers into their own file.
        let sources = vec![
            layer(
                INTEGRITY_CHECK_PATH,
                &format!(
                    "{}\n#[cfg(test)]\nmod tests;\n",
                    tests_support::clean_checksum_module()
                ),
            ),
            crate::size::LayerSource {
                crate_name: "waymaker-flash".to_owned(),
                path: "crates/waymaker-flash/src/crc/tests.rs".to_owned(),
                contents: "//! Checksum tests.\nmod data;\n".to_owned(),
            },
            crate::size::LayerSource {
                crate_name: "waymaker-flash".to_owned(),
                path: "crates/waymaker-flash/src/crc/tests/data.rs".to_owned(),
                contents: "//! Test helpers.\nstatic HELPER_TABLE: [u32; 16] = [0; 16];\n"
                    .to_owned(),
            },
        ];
        let violations = check_integrity_check(&sources);
        assert!(
            !violations.iter().any(|v| v.detail.contains("HELPER_TABLE")),
            "a test-only grandchild module was scanned as a shipped lookup table: \
             {violations:?}"
        );
    }

    #[test]
    fn a_lookup_table_in_a_checksum_submodule_is_reported() {
        // Codex, PR #58. Splitting `crc.rs` into `crc/mod.rs` and `crc/table.rs` is an
        // ordinary refactor, and it was how a table would arrive with the rule none the
        // wiser — it read one path and called everything else absent.
        let sources = vec![
            layer(
                INTEGRITY_CHECK_PATH,
                &tests_support::clean_checksum_module(),
            ),
            crate::size::LayerSource {
                crate_name: "waymaker-flash".to_owned(),
                path: "crates/waymaker-flash/src/crc/table.rs".to_owned(),
                contents: "pub(crate) const NIBBLE: [u32; 16] = [0; 16];\n".to_owned(),
            },
        ];
        let violations = check_integrity_check(&sources);
        assert!(
            violations
                .iter()
                .any(|v| v.detail.contains("NIBBLE") && v.detail.contains("crc/table.rs")),
            "a table in a checksum submodule went unseen: {violations:?}"
        );
    }

    #[test]
    fn a_dense_match_guarded_by_an_unsigned_right_shift_is_reported() {
        // Codex's next-round finding: `evaluate_binary_op` folded `Shr` the same way it
        // folded every other binary operator — as a plain signed `i128::checked_shr` over
        // the shared 128-bit storage — which is not sound for a `u128` shift the way an
        // ordinary bitwise operator's storage-agnostic bit pattern is. `u128::MAX >> 127`
        // is a real, unsigned, zero-filling shift `rustc` performs, landing on `1`; the
        // same bits reinterpreted as the stored `i128` (`-1`) shift arithmetically and
        // sign-extend, landing on `-1` again. A constant built from that shift therefore
        // resolved to the wrong value rather than merely staying unresolved, and a match
        // over constants derived from it went undetected. `evaluate_shift_op` now
        // reinterprets the left operand as `u128` before shifting, once
        // `is_definitely_unsigned` — recursing into the shifted expression itself, not
        // only into a literal, a cast or a bare path — confirms that is what its bits
        // mean.
        //
        // Writing this test surfaced a second, narrower gap in the same family:
        // `resolve_scope_consts`'s own local `resolve_unsigned` closure — used while
        // resolving `Q`'s own initializer, before any pattern is ever reached — answered
        // only for a bare name, never for a qualified reference or a well-known primitive
        // bound, on the reasoning (now stale) that this was the identical scope
        // `path_is_definitely_unsigned` itself declines beyond. `u128::MAX` is exactly a
        // qualified, well-known-bound reference, so `is_definitely_unsigned(u128::MAX)`
        // answered `false` inside `evaluate_shift_op` regardless of that function's own
        // fix, and `Q` stayed unresolved rather than merely wrong. Threaded to match
        // `path_is_definitely_unsigned`'s own two-step fallback instead. `40 / Q` through
        // `43 / Q`, rather than `Q * 0` through `Q * 3`, is deliberate: a wrongly-signed
        // `Q` still multiplies or adds into *some* contiguous window, just one shifted by
        // a constant amount, which this scan's own density check cannot tell apart from a
        // correct one — dividing a distinct dividend by the reinterpreted-as-`u128::MAX`
        // wrong answer collapses all four to `0` instead, which is not a window at all.
        let mut source = tests_support::clean_checksum_module();
        source.push_str(
            "\nconst fn unsigned_shift_pattern_table(nibble: u32) -> u32 {\n    \
             const Q: u128 = u128::MAX >> 127;\n    const P0: u128 = 40 / Q;\n    \
             const P1: u128 = 41 / Q;\n    const P2: u128 = 42 / Q;\n    const P3: u128 = 43 / Q;\n    \
             match nibble {\n        P0 => 0,\n        P1 => 1,\n        \
             P2 => 2,\n        P3 => 3,\n        _ => 4,\n    }\n}\n",
        );
        let violations = check_integrity_check(&[layer(INTEGRITY_CHECK_PATH, &source)]);
        assert!(
            violations
                .iter()
                .any(|violation| violation.detail.contains("declares a 5-arm dense match")),
            "{violations:?}"
        );
    }

    #[test]
    fn a_dense_match_guarded_by_a_u128_sum_crossing_the_i128_boundary_is_reported() {
        // Codex's next-round finding: `evaluate_binary_op` added two `u128` operands as
        // plain `i128::checked_add`, which refuses a sum that is a valid `u128` value but
        // exceeds `i128::MAX` — `(1u128 << 126) + (1u128 << 126)` is `2u128.pow(127)`, well
        // inside `u128`'s range and exactly what `rustc` computes, but one past what a
        // *signed* 128-bit addition can hold. The constant therefore stayed unresolved
        // rather than resolving to the wrong thing, and a match over constants derived
        // from it went undetected — the same shape of gap `evaluate_ordering_op` and
        // `evaluate_division_op` already closed for comparison and division, met here for
        // addition, subtraction and multiplication. `evaluate_additive_op` now retries as
        // `u128` once the signed attempt overflows and at least one operand is confirmed
        // unsigned, reinterpreting the result back into the shared storage.
        let mut source = tests_support::clean_checksum_module();
        source.push_str(
            "\nconst fn additive_overflow_pattern_table(nibble: u32) -> u32 {\n    \
             const BASE: u128 = (1u128 << 126) + (1u128 << 126);\n    \
             const P0: u128 = (BASE / BASE) * 0;\n    const P1: u128 = (BASE / BASE) * 1;\n    \
             const P2: u128 = (BASE / BASE) * 2;\n    const P3: u128 = (BASE / BASE) * 3;\n    \
             match nibble {\n        P0 => 0,\n        P1 => 1,\n        \
             P2 => 2,\n        P3 => 3,\n        _ => 4,\n    }\n}\n",
        );
        let violations = check_integrity_check(&[layer(INTEGRITY_CHECK_PATH, &source)]);
        assert!(
            violations
                .iter()
                .any(|violation| violation.detail.contains("declares a 5-arm dense match")),
            "{violations:?}"
        );
    }

    #[test]
    fn a_dense_match_guarded_by_a_cross_file_qualified_typed_constant_is_pruned_as_dead() {
        // Codex's next-round finding: an earlier round already gave `MatchVisitor` its own
        // `qualified_unsigned` mirror of `qualified`, so a guard qualified against an
        // *inline* `mod bounds { .. }` this same file declares already folds — but
        // `check_integrity_check_module_tree`'s own tree-wide `qualified` map, collected
        // from every file of the checksum module tree before any file is checked for a
        // dense match, had no unsignedness counterpart at all: `match_expressions_with_prefix`
        // was still seeded with an empty map regardless of what `qualified_unsigned` the
        // visitor itself would have produced. `bounds::HI` declared in a sibling
        // *out-of-line* `bounds.rs` therefore answered `false` for its own unsignedness no
        // matter how it was declared, because the file that would answer honestly was never
        // the file being checked. `qualified_constants_with_prefix` now returns its own
        // `qualified_unsigned` alongside `qualified`, collected across the tree the same
        // fixed-point pass already collects `qualified` with, and threaded through to
        // `match_expressions_with_prefix` instead of an empty map.
        let parent = format!(
            "{}\nmod bounds;\n\nconst fn cross_file_qualified_dead_guard_table(nibble: u8) -> \
             u32 {{\n    match nibble {{\n        0 => 0,\n        1 => 1,\n        \
             2 => 2,\n        _ if bounds::HI < bounds::ZERO => 999,\n        \
             _ => 3,\n    }}\n}}\n",
            tests_support::clean_checksum_module()
        );
        let bounds = "//! Bounds.\npub(crate) const HI: u128 = 1u128 << 127;\n\
                       pub(crate) const ZERO: u128 = 0;\n";
        let violations = check_integrity_check(&[
            layer(INTEGRITY_CHECK_PATH, &parent),
            layer("waymaker-flash/src/crc/bounds.rs", bounds),
        ]);
        assert!(
            violations
                .iter()
                .any(|violation| violation.detail.contains("declares a 4-arm dense match")),
            "{violations:?}"
        );
    }

